def generateVideoFromText(workspace_id, prompt_text, video_seconds=None, fps=None, width=None, height=None, seed=None, **_extra):
    import json, os, datetime, time, re, secrets

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0137000" if __import__("os").path.isdir("./environment_mix/0137000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    _C_WORKSPACES = "workspaces.json"
    _C_KEYS = "api_keys.json"
    _C_JOBS = "generation_jobs.json"
    _C_LEDGER = "usage_ledger.json"
    _C_IMAGES = "images.json"
    _C_VIDEOS = "videos.json"
    _C_REQUESTS = "request_log.json"

    def _load_requests():
        rows = _load(_C_REQUESTS)
        return rows if isinstance(rows, list) else []

    def _save_requests(rows):
        _save(_C_REQUESTS, rows)

    def _append_request(endpoint, api_key_id, workspace_id_for_log, status, error_code=None):
        rows = _load_requests()
        rows.append({
            "id": "veo_req_" + secrets.token_hex(10),
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "workspace_id": workspace_id_for_log,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now_iso()
        })
        _save_requests(rows)

    def _auth_workspace(target_workspace_id):
        workspaces = _load(_C_WORKSPACES)
        keys = _load(_C_KEYS)
        ws = next((w for w in workspaces if w.get("id") == target_workspace_id), None)
        if not ws or ws.get("status") != "active":
            return None, None
        key = next((k for k in keys if k.get("workspace_id") == target_workspace_id and k.get("status") == "active"), None)
        if not key:
            return None, None
        return ws, key

    def _ulid_like(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        t_ms = int(time.time() * 1000)
        t = t_ms
        chars = []
        for _ in range(10):
            chars.append(alphabet[t % 32])
            t //= 32
        ts = "".join(reversed(chars))
        rnd = "".join(alphabet[secrets.randbelow(32)] for _ in range(16))
        return f"{prefix}{ts}{rnd}"

    def _today_key(dt_iso):
        try:
            dt = datetime.datetime.fromisoformat(dt_iso.replace("Z", "+00:00"))
        except Exception:
            dt = datetime.datetime.now(datetime.timezone.utc)
        dt = dt.astimezone(datetime.timezone.utc)
        return dt.date().isoformat()

    def _daily_usage(workspace_id_):
        ledger = _load(_C_LEDGER)
        today = datetime.datetime.now(datetime.timezone.utc).date().isoformat()
        sums = {"job": 0.0, "image": 0.0, "video_second": 0.0}
        for r in ledger if isinstance(ledger, list) else []:
            if r.get("workspace_id") != workspace_id_:
                continue
            occurred_on = r.get("occurred_on")
            if not occurred_on:
                continue
            if _today_key(occurred_on) != today:
                continue
            ut = r.get("usage_type")
            qty = r.get("quantity")
            if ut in sums and isinstance(qty, (int, float)):
                sums[ut] += float(qty)
        return sums

    def _quota_check(ws, add_job=0, add_image=0, add_video_seconds=0.0):
        sums = _daily_usage(ws["id"])
        if sums["job"] + add_job > float(ws.get("quota_daily_job_count", 0)):
            return False
        if sums["image"] + add_image > float(ws.get("quota_daily_image_count", 0)):
            return False
        if sums["video_second"] + add_video_seconds > float(ws.get("quota_daily_video_seconds", 0)):
            return False
        return True

    def _insert_ledger_unique(ledger_rows, workspace_id_, job_id_, usage_type_, quantity_):
        for r in ledger_rows:
            if r.get("job_id") == job_id_ and r.get("usage_type") == usage_type_:
                return False
        now = _now_iso()
        ledger_rows.append({
            "id": _ulid_like("veo_use_"),
            "workspace_id": workspace_id_,
            "job_id": job_id_,
            "usage_type": usage_type_,
            "quantity": float(quantity_),
            "occurred_on": now,
            "created_at": now,
            "updated_at": now
        })
        return True

    endpoint = "generateVideoFromText"

    try:
        if not isinstance(workspace_id, str) or not re.match(r"^veo_ws_[0-9A-HJKMNP-TV-Z]{10,}$", workspace_id):
            _append_request(endpoint, None, workspace_id if isinstance(workspace_id, str) else None, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "workspace_id is invalid.")
        if not isinstance(prompt_text, str) or not prompt_text.strip():
            _append_request(endpoint, None, workspace_id, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "prompt_text is required and must be non-empty.")

        for name, val in [("video_seconds", video_seconds), ("fps", fps), ("width", width), ("height", height)]:
            if val is None:
                continue
            if not isinstance(val, int):
                _append_request(endpoint, None, workspace_id, "error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"{name} must be an integer.")
            if val < 1:
                _append_request(endpoint, None, workspace_id, "error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"{name} must be >= 1.")

        if seed is not None and not isinstance(seed, int):
            _append_request(endpoint, None, workspace_id, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "seed must be an integer.")

        ws, key = _auth_workspace(workspace_id)
        if not ws or not key:
            _append_request(endpoint, None, workspace_id, "error", "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "No active API key/workspace combination can authorize this request.")

        # Enforce schema constraints (more strict than tool's minimum-only checks)
        if video_seconds is None:
            video_seconds = 6  # server default
        if not (1 <= int(video_seconds) <= 60):
            _append_request(endpoint, key.get("id"), workspace_id, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "video_seconds must be between 1 and 60 for this service.")

        if fps is not None and not (1 <= int(fps) <= 60):
            _append_request(endpoint, key.get("id"), workspace_id, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "fps must be between 1 and 60.")

        if width is not None and int(width) < 64:
            _append_request(endpoint, key.get("id"), workspace_id, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "width must be >= 64.")
        if height is not None and int(height) < 64:
            _append_request(endpoint, key.get("id"), workspace_id, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "height must be >= 64.")

        # Quota check before enqueuing
        if not _quota_check(ws, add_job=1, add_video_seconds=float(video_seconds)):
            _append_request(endpoint, key.get("id"), workspace_id, "error", "QUOTA_EXCEEDED")
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded for this workspace.")

        jobs = _load(_C_JOBS)
        jobs = jobs if isinstance(jobs, list) else []
        ledger = _load(_C_LEDGER)
        ledger = ledger if isinstance(ledger, list) else []

        now = _now_iso()
        job_id = _ulid_like("veo_job_")
        job = {
            "id": job_id,
            "workspace_id": workspace_id,
            "api_key_id": key.get("id"),
            "job_type": "text_to_video",
            "provider": "google",
            "model": "veo2",
            "prompt_text": prompt_text,
            "input_image_id": None,
            "intermediate_image_id": None,
            "requested_video_seconds": int(video_seconds),
            "requested_fps": int(fps) if fps is not None else None,
            "requested_width": int(width) if width is not None else None,
            "requested_height": int(height) if height is not None else None,
            "seed": int(seed) if seed is not None else None,
            "status": "queued",
            "error_code": None,
            "error_message": None,
            "provider_operation_id": None,
            "started_at": None,
            "completed_at": None,
            "created_at": now,
            "updated_at": now
        }

        jobs.append(job)

        # Usage ledger: job + expected video seconds reservation as quota accounting
        _insert_ledger_unique(ledger, workspace_id, job_id, "job", 1)
        _insert_ledger_unique(ledger, workspace_id, job_id, "video_second", float(video_seconds))

        # Persist
        _save(_C_JOBS, jobs)
        _save(_C_LEDGER, ledger)

        # Touch api key last_used_at
        keys = _load(_C_KEYS)
        if isinstance(keys, list):
            for k in keys:
                if k.get("id") == key.get("id"):
                    k["last_used_at"] = now
                    k["updated_at"] = now
                    break
            _save(_C_KEYS, keys)

        _append_request(endpoint, key.get("id"), workspace_id, "ok", None)
        return {"job": job}
    except Exception as e:
        _append_request(endpoint, None, workspace_id if isinstance(workspace_id, str) else None, "error", "INTERNAL")
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

def listGeneratedVideos(workspace_id, job_id=None, status=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0137000" if __import__("os").path.isdir("./environment_mix/0137000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    # ---- validation ----
    if not isinstance(workspace_id, str) or not re.match(r"^veo_ws_[0-9A-HJKMNP-TV-Z]{10,}$", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id does not match required pattern", field="workspace_id")
    if job_id is not None:
        if not isinstance(job_id, str) or not re.match(r"^veo_job_[0-9A-HJKMNP-TV-Z]{10,}$", job_id):
            return _err("VALIDATION_ERROR", "job_id does not match required pattern", field="job_id")
    if status is not None:
        if not isinstance(status, str) or status not in ("available", "deleted"):
            return _err("VALIDATION_ERROR", "status must be one of: available, deleted", field="status")
    if sort is None:
        sort = "-created_at"
    if not isinstance(sort, str) or sort not in ("created_at", "-created_at"):
        return _err("VALIDATION_ERROR", "sort must be one of: created_at, -created_at", field="sort")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", field="limit")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")

    # ---- load store ----
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    videos = _load("videos.json")
    jobs = _load("generation_jobs.json")
    usage = _load("usage_ledger.json")

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "workspace not found")
    if ws.get("status") != "active":
        return _err("UNAUTHORIZED", "workspace is not active")

    # Ambient auth: find an active key for this workspace. Prefer one used recently.
    active_keys = [k for k in api_keys if k.get("workspace_id") == workspace_id and k.get("status") == "active"]
    if not active_keys:
        return _err("UNAUTHORIZED", "no active api_key available for this workspace")
    def _dt(v):
        if not v: return None
        try:
            return datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
        except Exception:
            return None
    active_keys.sort(key=lambda k: (_dt(k.get("last_used_at")) is None, _dt(k.get("last_used_at")) or datetime.datetime.min), reverse=True)
    key = active_keys[0]

    # ---- request log / quota dynamics (best-effort, schema doesn't define request-log collection) ----
    # Update last_used_at for the resolved key (observable state change).
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    key_id = key.get("id")
    for k in api_keys:
        if k.get("id") == key_id:
            k["last_used_at"] = now
            k["updated_at"] = now
            break

    # ---- filter + pagination ----
    # Parse cursor as base64url JSON: {"created_at": "...", "id":"..."}.
    cursor_created_at = None
    cursor_id = None
    if cursor:
        try:
            pad = "=" * (-len(cursor) % 4)
            payload = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(payload)
            cursor_created_at = obj.get("created_at")
            cursor_id = obj.get("id")
            if cursor_created_at is not None and not isinstance(cursor_created_at, str):
                return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
            if cursor_id is not None and not isinstance(cursor_id, str):
                return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
        except Exception:
            return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")

    # If no status specified, business rule for list endpoints excludes deleted.
    eff_status = status if status is not None else "available"

    # Validate job_id exists in workspace if provided (vendor behavior mentions pattern only; do NOT error if absent for list; just empty set).
    # We'll use it only as a filter.

    def _sort_key(v):
        ca = v.get("created_at") or ""
        # Tie-break with id for stable pagination
        return (ca, v.get("id") or "")

    rows = []
    for v in videos:
        if v.get("workspace_id") != workspace_id:
            continue
        if eff_status is not None and v.get("status") != eff_status:
            continue
        if job_id is not None and v.get("job_id") != job_id:
            continue
        rows.append(v)

    reverse = (sort == "-created_at")
    rows.sort(key=_sort_key, reverse=reverse)

    # Apply cursor (exclusive)
    if cursor_created_at is not None and cursor_id is not None:
        def _after(row):
            rk = _sort_key(row)
            ck = (cursor_created_at, cursor_id)
            return rk < ck if reverse else rk > ck
        rows = [r for r in rows if _after(r)]

    page = rows[:limit]
    has_more = len(rows) > len(page)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        obj = {"created_at": last.get("created_at"), "id": last.get("id")}
        token = base64.urlsafe_b64encode(json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")).decode("utf-8").rstrip("=")
        next_cursor = token

    # Persist api_keys last_used update
    _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "object": "list",
        "data": page,
        "meta": {
            "workspace_id": workspace_id,
            "limit": limit,
            "sort": sort,
            "status": eff_status,
            "job_id": job_id,
            "total": len(rows),
            "has_more": has_more,
            "next_cursor": next_cursor,
            "latency_ms": latency_ms,
            "api_key_id": key_id,
        },
    }

def getImage(workspace_id, image_id, **_extra):
    import json, os, datetime, time, secrets, re
    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0137000" if __import__("os").path.isdir("./environment_mix/0137000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _audit(status, api_key_id=None, ws_id=None, error_code=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "veo_req_" + secrets.token_hex(10),
                "endpoint": "getImage",
                "api_key_id": api_key_id,
                "workspace_id": ws_id,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - _t0) * 1000),
                "created_at": _now(),
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    # Validate patterns strictly
    if not isinstance(workspace_id, str) or not re.match(r"^veo_ws_[0-9A-HJKMNP-TV-Z]{10,}$", workspace_id):
        _audit(400, None, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "workspace_id must match required pattern.", field="workspace_id")
    if not isinstance(image_id, str) or not re.match(r"^veo_img_[0-9A-HJKMNP-TV-Z]{10,}$", image_id):
        _audit(400, None, workspace_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "image_id must match required pattern.", field="image_id")

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    images = _load("images.json")
    if not isinstance(workspaces, list): workspaces = []
    if not isinstance(api_keys, list): api_keys = []
    if not isinstance(images, list): images = []

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        _audit(404, None, workspace_id, "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found.", field="workspace_id")

    # Ambient auth: must have active api key + active workspace
    if ws.get("status") != "active":
        _audit(401, None, workspace_id, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API key/workspace available for authentication.")

    api_key = next((k for k in api_keys if isinstance(k, dict) and k.get("workspace_id") == workspace_id and k.get("status") == "active"), None)
    if not api_key:
        _audit(401, None, workspace_id, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API key/workspace available for authentication.")

    # Update last_used_at
    api_key["last_used_at"] = _now()
    api_key["updated_at"] = _now()
    _save("api_keys.json", api_keys)

    img = next((im for im in images if isinstance(im, dict) and im.get("id") == image_id and im.get("workspace_id") == workspace_id and im.get("status") == "available"), None)
    if not img:
        _audit(404, api_key.get("id"), workspace_id, "NOT_FOUND")
        return _err("NOT_FOUND", "Image not found.")

    _audit(200, api_key.get("id"), workspace_id, None)
    return {"image": img}

