            return None

    active_keys.sort(key=lambda k: (_dt(k.get("last_used_at")) is None, _dt(k.get("last_used_at")) or datetime.datetime.min), reverse=True)
    key = active_keys[0]

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    for k in api_keys:
        if k.get("id") == key.get("id"):
            k["last_used_at"] = now
            k["updated_at"] = now
            break

    cursor_created_at = None
    cursor_id = None
    if cursor:
        try:
            pad = "=" * (-len(cursor) % 4)
            payload = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(payload)
            cursor_created_at = obj.get("created_at")
            cursor_id = obj.get("id")
            if cursor_created_at is not None and not isinstance(cursor_created_at, str):
