def listJobs(status=None, job_type=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0137000" if __import__("os").path.isdir("./environment_mix/0137000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- helpers
    def _audit(endpoint, api_key_id, workspace_id, status_code, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "workspace_id": workspace_id,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": now
        })
        _save("request_logs.json", logs)

    def _parse_ts(v):
        if not v:
            return None
        if isinstance(v, (int, float)):
            return float(v)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1]
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt.replace(tzinfo=None).timestamp()
            except Exception:
                return None
        return None

    def _decode_cursor(c):
        if not c:
            return None
        if not isinstance(c, str):
            return None
        try:
            pad = "=" * (-len(c) % 4)
            raw = base64.urlsafe_b64decode((c + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict):
                return None
            return obj
        except Exception:
            return None

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # --- validate inputs
    valid_status = {"queued", "running", "succeeded", "failed", "cancelled"}
    valid_job_type = {"text_to_video", "image_to_video", "text_to_image", "text_to_image_to_video"}

    if status is not None and (not isinstance(status, str) or status not in valid_status):
        _audit("listJobs", None, None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'status' filter.", field="status")

    if job_type is not None and (not isinstance(job_type, str) or job_type not in valid_job_type):
        _audit("listJobs", None, None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'job_type' filter.", field="job_type")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _audit("listJobs", None, None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'limit'. Must be an integer between 1 and 100.", field="limit")

    if cursor is not None and not isinstance(cursor, str):
        _audit("listJobs", None, None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'cursor'. Must be a string.", field="cursor")

    # --- ambient auth: choose any active api_key in an active workspace
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")

    ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict)}
    active_pairs = []
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        ws = ws_by_id.get(k.get("workspace_id"))
        if ws and ws.get("status") == "active":
            active_pairs.append((ws, k))

    if not active_pairs:
        _audit("listJobs", None, None, 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API key/workspace available for authentication.")

    workspace, api_key = active_pairs[0]
    workspace_id = workspace["id"]
    api_key_id = api_key["id"]

    # update last_used_at
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == api_key_id:
            k["last_used_at"] = now
            k["updated_at"] = k.get("updated_at") or now
            break
    _save("api_keys.json", api_keys)

    jobs = _load("generation_jobs.json")
    if not isinstance(jobs, list):
        jobs = []

    # filter to workspace + optional filters
    rows = []
    for j in jobs:
        if not isinstance(j, dict):
            continue
        if j.get("workspace_id") != workspace_id:
            continue
        if status is not None and j.get("status") != status:
            continue
        if job_type is not None and j.get("job_type") != job_type:
            continue
        rows.append(j)

    # newest first by created_at desc (fallback id)
    def _sort_key(j):
        ts = _parse_ts(j.get("created_at")) or 0.0
        return (ts, str(j.get("id") or ""))

    rows.sort(key=_sort_key, reverse=True)

    # pagination
    start = 0
    cobj = _decode_cursor(cursor) if cursor else None
    if cursor:
        if not cobj or cobj.get("workspace_id") != workspace_id or "offset" not in cobj:
            _audit("listJobs", api_key_id, workspace_id, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid 'cursor'.", field="cursor")
        off = cobj.get("offset")
        if not isinstance(off, int) or off < 0:
            _audit("listJobs", api_key_id, workspace_id, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid 'cursor' offset.", field="cursor")
        start = off

    total = len(rows)
    page = rows[start:start + limit]
    next_cursor = None
    has_more = start + limit < total
    if has_more:
        next_cursor = _encode_cursor({"workspace_id": workspace_id, "offset": start + limit})

    _audit("listJobs", api_key_id, workspace_id, 200, None)
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def cancelJob(job_id, reason=None, **_extra):
    import json, os, datetime, time, secrets, re
    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0137000" if __import__("os").path.isdir("./environment_mix/0137000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _audit(status, api_key_id=None, ws_id=None, error_code=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "veo_req_" + secrets.token_hex(10),
                "endpoint": "cancelJob",
                "api_key_id": api_key_id,
                "workspace_id": ws_id,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - _t0) * 1000),
                "created_at": _now(),
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    if not isinstance(job_id, str) or not re.match(r"^veo_job_[0-9A-HJKMNP-TV-Z]{10,}$", job_id):
        _audit(400, None, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "job_id must match required pattern.", field="job_id")
    if reason is not None and not isinstance(reason, str):
        _audit(400, None, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "reason must be a string.", field="reason")

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    jobs = _load("generation_jobs.json")
    if not isinstance(workspaces, list): workspaces = []
    if not isinstance(api_keys, list): api_keys = []
    if not isinstance(jobs, list): jobs = []

    idx = None
    job = None
    for i, j in enumerate(jobs):
        if isinstance(j, dict) and j.get("id") == job_id:
            idx = i
            job = j
            break
    if job is None:
        _audit(404, None, None, "NOT_FOUND")
        return _err("NOT_FOUND", "Job not found.")

    ws_id = job.get("workspace_id")
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == ws_id), None)
    if not ws or ws.get("status") != "active":
        _audit(404, None, ws_id, "NOT_FOUND")
        return _err("NOT_FOUND", "Job not found.")

    # Ambient auth: any active api key for that workspace
    api_key = next((k for k in api_keys if isinstance(k, dict) and k.get("workspace_id") == ws_id and k.get("status") == "active"), None)
    if not api_key:
        _audit(401, None, ws_id, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API key/workspace available for authentication.")

    # Update last_used_at
    api_key["last_used_at"] = _now()
    api_key["updated_at"] = _now()
    _save("api_keys.json", api_keys)

    # Enforce lifecycle transition to cancelled
    current = job.get("status")
    transitions = {
        "queued": ["running", "cancelled", "failed"],
        "running": ["succeeded", "failed", "cancelled"],
        "succeeded": [],
        "failed": [],
        "cancelled": [],
    }
    if current not in transitions:
        _audit(409, api_key.get("id"), ws_id, "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Job is in an unknown state and cannot be cancelled.")

    if "cancelled" not in transitions[current]:
        # Vendor description says CONFLICT for terminal/non-cancellable
        _audit(409, api_key.get("id"), ws_id, "CONFLICT")
        return _err("CONFLICT", "Job cannot be cancelled from its current state.", field="status")

    # Apply transition
    now = _now()
    job["status"] = "cancelled"
    job["updated_at"] = now
    job["completed_at"] = now  # terminal implies completed_at
    job["error_code"] = "USER_CANCELLED"
    if isinstance(reason, str) and reason.strip():
        job["error_message"] = reason.strip()
    else:
        job["error_message"] = job.get("error_message") or "Cancelled by user."
    jobs[idx] = job
    _save("generation_jobs.json", jobs)

    _audit(200, api_key.get("id"), ws_id, None)
    return {"job": job}

